-- Clean up prior tables if present
DROP TABLE IF EXISTS tickets CASCADE;
DROP TABLE IF EXISTS flights CASCADE;
DROP TABLE IF EXISTS passengers CASCADE;
DROP TABLE IF EXISTS airports CASCADE;

-- 1. Airports Lookup Table
CREATE TABLE airports (
    airport_code VARCHAR(3) PRIMARY KEY,
    airport_name VARCHAR(100) NOT NULL,
    city VARCHAR(50) NOT NULL,
    state VARCHAR(2) NOT NULL
);

-- 2. Passengers Table
CREATE TABLE passengers (
    passenger_id SERIAL PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    loyalty_tier VARCHAR(20) NOT NULL
);

-- 3. Flights Table
CREATE TABLE flights (
    flight_id SERIAL PRIMARY KEY,
    flight_number VARCHAR(10) NOT NULL,
    origin_code VARCHAR(3) NOT NULL REFERENCES airports(airport_code),
    dest_code VARCHAR(3) NOT NULL REFERENCES airports(airport_code),
    departure_time TIMESTAMP NOT NULL,
    aircraft_type VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL
);

-- 4. Tickets Transaction Table
CREATE TABLE tickets (
    ticket_id SERIAL PRIMARY KEY,
    flight_id INT NOT NULL REFERENCES flights(flight_id),
    passenger_id INT NOT NULL REFERENCES passengers(passenger_id),
    seat_number VARCHAR(5) NOT NULL,
    fare_class VARCHAR(20) NOT NULL,
    ticket_price NUMERIC(7,2) NOT NULL
);

